    parent = {}
    nodes = set()
    for i in range(m):
        p, l, r = int(data[1 + 3 * i]), int(data[2 + 3 * i]), int(data[3 + 3 * i])
        if p in kids:
            print(-1)
            return
        kids[p] = (l, r)
        nodes.add(p)
        for c in (l, r):
            if c != -1:
                if c == p or c in parent:
                    print(-1)
                    return
                parent[c] = p
                nodes.add(c)
    roots = [v for v in nodes if v not in parent]
    if len(roots) != 1:
        print(-1)
        return
    root = roots[0]
    INF = 1 << 60
    stack = [(root, -INF, INF)]
    seen = 0
    while stack:
        v, lo, hi = stack.pop()
        seen += 1
        if not (lo < v < hi):
            print(-1)
            return
        l, r = kids.get(v, (-1, -1))
        if l != -1:
            stack.append((l, lo, v))
        if r != -1:
            stack.append((r, v, hi))
    print(root if seen == len(nodes) else -1)

