data = sys.stdin.read().split()
m = int(data[0])
trip = [(int(data[1 + 3 * i]), int(data[2 + 3 * i]), int(data[3 + 3 * i])) for i in range(m)]

def solve():
    parents = [t[0] for t in trip]
    if len(parents) != len(set(parents)):
        return -1
    nodes = set(parents)
    child_list = []
    for p, l, r in trip:
        for c in (l, r):
            if c != -1:
                child_list.append(c)
                nodes.add(c)
    if len(child_list) != len(set(child_list)):
        return -1
    roots = [v for v in nodes if v not in child_list]
    if len(roots) != 1:
        return -1
    ch = {p: (l, r) for p, l, r in trip}
    order = []
    visited = set()
    ok = [True]
    def go(v):
        if v in visited:
            ok[0] = False
            return
        visited.add(v)
        l, r = ch.get(v, (-1, -1))
        if l != -1:
            go(l)
        order.append(v)
        if r != -1:
            go(r)
    go(roots[0])
    if not ok[0] or len(visited) != len(nodes):
        return -1
    for i in range(len(order) - 1):
        if order[i] >= order[i + 1]:
            return -1
    return roots[0]

print(solve())

